"""Basketball control through the public robot client only; never resets.
All executed targets are logged in actions.jsonl. replay() sends that record.
"""
import argparse
import json
from pathlib import Path
import numpy as np
from rcb_client import Robot

OUT = Path('/app/output')
OUT.mkdir(exist_ok=True)
SPEC = json.loads((OUT/'spec.json').read_text())
RANGES = np.array(SPEC['action_types']['joint_position']['range_rad'])

def normalized(q):
    return np.clip(2*(np.asarray(q)-RANGES[:,0])/(RANGES[:,1]-RANGES[:,0])-1,-1,1)

def record(res, name):
    res.save(str(OUT/name))
    for cam, im in res.last.items():
        from PIL import Image
        Image.fromarray(im).save(OUT/name/(cam+'.png'))
    (OUT/'latest.json').write_text(json.dumps(res.meta))
    print(json.dumps({'step':res.meta['control_steps'],'done':res.done,'reason':res.meta.get('reason'),'q':res.meta['proprio']['now'][:19], 'vel':res.meta['proprio']['now'][19:38], 'imu':res.meta['proprio']['now'][38:]}))
    return res

def move(q, n=1, name=None):
    r=Robot()
    A=normalized(q)
    if A.ndim==1: A=np.tile(A,(n,1))
    start=r.status()['control_steps']
    name=name or f'step_{start+len(A):03d}'
    with (OUT/'actions.jsonl').open('a') as f:
        f.write(json.dumps({'start':start,'name':name,'actions':A.tolist()})+'\n')
    return record(r.submit('joint_position',A,dt=.02,interpolate='hold',video='frames',video_fps=30),name)

def observe(name='observation'):
    return record(Robot().get_obs(),name)

def replay():
    r=Robot()
    for line in (OUT/'actions.jsonl').read_text().splitlines():
        entry=json.loads(line)
        res=r.submit('joint_position',entry['actions'],dt=.02,interpolate='hold',video='none')
        if res.done:break
    return res

if __name__=='__main__':
    p=argparse.ArgumentParser()
    p.add_argument('--q',type=str)
    p.add_argument('--steps',type=int,default=1)
    p.add_argument('--name')
    p.add_argument('--replay',action='store_true')
    a=p.parse_args()
    if a.replay:replay()
    elif a.q:move(json.loads(a.q),a.steps,a.name)
    else:observe(a.name or 'observation')
