import json
import numpy as np
from scipy.spatial.transform import Rotation
from scipy.optimize import least_squares
from pathlib import Path
SPEC=json.loads(Path('/app/output/spec.json').read_text())
AX=np.array(SPEC['proprio']['axis']); POS=np.array(SPEC['proprio']['position_m'])

def rot(axis,a):
    axis=np.array(axis);return Rotation.from_rotvec(axis/np.linalg.norm(axis)*a).as_matrix()

def point_fk(q, p, chain):
    R=np.eye(3);t=np.zeros(3)
    for i in chain:
        r=rot(AX[i],q[i]);t=t+R@(POS[i]-r@POS[i]);R=R@r
    return R@p+t

def hand(q,left=True):
    ids=[10]+(list(range(11,15)) if left else list(range(15,19)))
    p=np.array([.329,.214 if left else -.214,.097])
    return point_fk(q,p,ids)

def arm_ik(target,left=True,q=None):
    q=np.zeros(19) if q is None else np.array(q).copy()
    ids=list(range(11,15)) if left else list(range(15,19))
    limits=np.array(SPEC['action_types']['joint_position']['range_rad'])[ids]
    def err(v):
        qq=q.copy();qq[ids]=v
        return np.r_[10*(hand(qq,left)-target),.03*(v-q[ids])]
    res=least_squares(err,q[ids],bounds=(limits[:,0]+.001,limits[:,1]-.001),max_nfev=300)
    q[ids]=res.x
    return q,hand(q,left)

cam=SPEC['cameras']['room_camera']['pose'];CP=np.array(cam['position_m']);CF=np.array(cam['forward']);CU=np.array(cam['up']);CR=np.array(cam['right']);F=128/np.tan(np.pi/8)
def project(p):
    d=np.asarray(p)-CP
    return np.array([127.5+F*(d@CR)/(d@CF),127.5-F*(d@CU)/(d@CF)])
def ray(uv):return CF+(uv[0]-127.5)/F*CR-(uv[1]-127.5)/F*CU

def ball_pixels(path):
    from PIL import Image
    import cv2
    im=np.array(Image.open(path));r,g,b=im.astype(float).transpose(2,0,1)
    mask=((r>g*1.35)&(g>b*1.25)&(r>65)).astype('uint8')
    n,l,stats,c=cv2.connectedComponentsWithStats(mask)
    if n<2:return None
    k=1+np.argmax(stats[1:,4]);m=l==k; ys,xs=np.where(m)
    return c[k],(np.min(xs),np.max(xs),np.min(ys),np.max(ys)),stats[k,4]
if __name__=='__main__':
    import sys
    for path in sys.argv[1:]:
        bp=ball_pixels(path); print(path,bp)
        if bp: print('ray',ray(bp[0]),'assuming y0',CP-ray(bp[0])*CP[1]/ray(bp[0])[1])
    q=np.zeros(19);q[[11,15]]=-.5;q[[14,18]]=-.4
    print('hands',hand(q),hand(q,False))
